const raw = $input.first().json;
const e = raw.body ?? raw;
let texto = '';
switch (e.evento) {
  case 'VISITA_CRIADA':
    texto = `Olá, ${e.nome}! 🐶\n\nSua visita ao ${e.siteName} foi agendada.\n\n${e.linkGerenciamento}\n\nToque no link acima para reagendar ou cancelar.`;
    break;
  case 'VISITA_REAGENDADA':
    texto = `Olá, ${e.nome}! Sua visita foi reagendada.\n\n${e.linkGerenciamento}`;
    break;
  case 'VISITA_CANCELADA':
    texto = `Olá, ${e.nome}. Sua visita foi cancelada. Para marcar de novo, fale conosco no WhatsApp.`;
    break;
  case 'VISITA_CONFIRMADA':
    texto = `Olá, ${e.nome}! ✅ Visita confirmada.\n\n${e.linkGerenciamento}`;
    break;
  case 'VISITA_LEMBRETE':
    texto = `Olá, ${e.nome}! Lembrete: você tem visita agendada em breve.\n\n${e.linkGerenciamento}`;
    break;
  default:
    texto = `Olá, ${e.nome}! ${e.linkGerenciamento || ''}`;
}
if (!e.telefoneWhatsApp) throw new Error('telefoneWhatsApp ausente no payload');
return [{ json: { ...e, textoWhatsApp: texto } }];
